async function readBody(request: IncomingMessage, limit: number): Promise<Json> { const chunks: Buffer[] = []; let size = 0; for await (const chunk of request) { const bytes = Buffer.from(chunk); size += bytes.length; if (size > limit) throw new Error("request body is too large"); chunks.push(bytes); } const parsed: unknown = JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}"); if (!jsonValue(parsed)) throw new Error("request body must be finite JSON"); return parsed; }
